CREATE TABLE aggregate_projections(tenant_id uuid NOT NULL,branch_id uuid,producer varchar(32) NOT NULL,aggregate_type varchar(80) NOT NULL,aggregate_id uuid NOT NULL,aggregate_version bigint NOT NULL,event_id uuid NOT NULL,snapshot jsonb NOT NULL,occurred_at timestamptz NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,producer,aggregate_type,aggregate_id));
CREATE INDEX projection_branch ON aggregate_projections(tenant_id,branch_id,producer,aggregate_type);
CREATE TABLE projection_checkpoints(consumer_name varchar(80) NOT NULL,producer varchar(32) NOT NULL,last_event_id uuid,occurred_at timestamptz,processed_at timestamptz NOT NULL DEFAULT now(),reconciled_at timestamptz,reconciliation_cursor timestamptz NOT NULL DEFAULT 'epoch',reconciliation_event_id uuid NOT NULL DEFAULT '00000000-0000-0000-0000-000000000000',PRIMARY KEY(consumer_name,producer));
CREATE VIEW branch_booking_metrics AS SELECT tenant_id,branch_id,count(*) AS bookings,count(*) FILTER(WHERE snapshot->>'status'='CONFIRMED') AS confirmed,count(*) FILTER(WHERE snapshot->>'status'='CANCELLED') AS cancelled FROM aggregate_projections WHERE producer='booking' AND aggregate_type='appointments' GROUP BY tenant_id,branch_id;
CREATE VIEW branch_workorder_metrics AS SELECT tenant_id,branch_id,count(*) FILTER(WHERE snapshot->>'completedAt' IS NOT NULL) AS completed_work_orders,avg(extract(epoch from ((snapshot->>'completedAt')::timestamptz-(snapshot->>'checkInAt')::timestamptz))/60) FILTER(WHERE snapshot->>'completedAt' IS NOT NULL AND snapshot->>'checkInAt' IS NOT NULL) AS average_turnaround_minutes FROM aggregate_projections WHERE producer='workorder' AND aggregate_type='work_orders' GROUP BY tenant_id,branch_id;
CREATE VIEW branch_billing_metrics AS SELECT tenant_id,branch_id,snapshot->>'currency' AS currency,count(*) FILTER(WHERE aggregate_type='invoices' AND snapshot->>'status'='ISSUED') AS issued_invoices,coalesce(sum((snapshot->>'amount')::numeric) FILTER(WHERE aggregate_type='invoices' AND snapshot->>'status'='ISSUED'),0) AS issued_invoice_value,coalesce(sum(CASE WHEN snapshot->>'recordType'='REFUND' THEN -(snapshot->>'amount')::numeric ELSE (snapshot->>'amount')::numeric END) FILTER(WHERE aggregate_type='payments'),0) AS recorded_payment_collections,count(*) FILTER(WHERE aggregate_type='estimates' AND snapshot->>'status'='PENDING_CUSTOMER_APPROVAL') AS pending_approvals FROM aggregate_projections WHERE producer='billing' GROUP BY tenant_id,branch_id,snapshot->>'currency';
